"""Repair MathType WMF fonts; standalone copies are generated by the builder."""
import io
from pathlib import Path
import struct
import re


def _records(data):
    start = 22 if data[:4] == b'\xd7\xcd\xc6\x9a' else 0
    if len(data) < start + 18:
        raise ValueError('invalid WMF header')
    offset = start + 18
    while offset + 6 <= len(data):
        words, function = struct.unpack_from('<IH', data, offset)
        end = offset + words * 2
        if words < 3 or end > len(data):
            raise ValueError('invalid WMF record')
        yield offset, function, data[offset + 6:end]
        if function == 0:
            return
        offset = end


def _render_real_number_symbol():
    from PIL import Image, ImageDraw, ImageFont
    candidates = [Path('C:/Windows/Fonts/cambria.ttc'),
                  Path('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'),
                  Path('/usr/share/fonts/truetype/dejavu/DejaVuSansCondensed.ttf')]
    path = next((p for p in candidates if p.is_file()), None)
    if path is None:
        raise ValueError('Euclid Extra real-number glyph requires Cambria or fonts-dejavu-core')
    font = ImageFont.truetype(str(path), 240)
    box = font.getbbox('\u211d')
    image = Image.new('RGB', (box[2] - box[0] + 48, box[3] - box[1] + 48), 'white')
    ImageDraw.Draw(image).text((24 - box[0], 24 - box[1]), '\u211d', font=font, fill='black')
    stream = io.BytesIO()
    image.save(stream, 'PNG')
    return stream.getvalue()


def prepare_wmf(data):
    """Repair verified font aliases/charset; preserve unknown encodings for review.

    Font records have fixed 32-byte names, so record lengths stay intact.
    Euclid Extra 0xA1 is supported only as an isolated real-number-set glyph.
    """
    records = list(_records(data))
    fonts, texts = [], []
    drawings = {0x213, 0x324, 0x325, 0x41B, 0x418, 0x817, 0x830, 0xB41, 0xF43}
    for _, function, payload in records:
        if function == 0x2FB and len(payload) >= 50:
            fonts.append(payload[18:50].split(b'\0', 1)[0].decode('ascii', errors='replace'))
        elif function == 0xA32 and len(payload) >= 8:
            count, flags = struct.unpack_from('<HH', payload, 4)
            start = 16 if flags & 6 else 8
            texts.append(payload[start:start + count])
        elif function == 0x521 and len(payload) >= 2:
            count = struct.unpack_from('<H', payload)[0]
            texts.append(payload[2:2 + count])
    if 'Euclid Extra' in fonts:
        if (texts == [b'\xa1'] and fonts[0] == 'Euclid Extra'
                and not any(function in drawings for _, function, _ in records)):
            return _render_real_number_symbol(), 'png'
        raise ValueError('unsupported Euclid Extra encoding; preserve vector for review')
    repaired = bytearray(data)
    for offset, function, payload in records:
        if function != 0x2FB or len(payload) < 50:
            continue
        name = payload[18:50].split(b'\0', 1)[0]
        replacement = {b'Euclid': b'Times New Roman', b'Euclid Symbol': b'Symbol'}.get(name)
        if replacement:
            repaired[offset + 24:offset + 56] = replacement.ljust(32, b'\0')
        if name in {b'Euclid Symbol', b'Symbol'}:
            repaired[offset + 19] = 2  # SYMBOL_CHARSET: 0xA5 is infinity, not yen.
    return bytes(repaired), 'wmf'


def read_wmf_number(data):
    """Decode one numeric text run, optionally preceded spatially by a sign.

    Accept only equal-size runs on one baseline; spatial math, drawing,
    scripts and unknown fonts always fall through to OCR.
    """
    try:
        records = list(_records(data))
    except ValueError:
        return None
    objects, runs = [], []
    current, position, alignment = None, (0, 0), 0
    normal = {'Euclid', 'Times New Roman', 'Arial', 'Cambria', 'Calibri', 'System'}
    for _, function, payload in records:
        if function in {0x213, 0x324, 0x325, 0x41B, 0x418, 0x817, 0x830, 0xB41, 0xF43, 0x2FA, 0x2FC}:
            return None
        if function == 0x2FB and len(payload) >= 50:
            item = (payload[18:50].split(b'\0', 1)[0].decode('ascii', errors='replace'),
                    abs(struct.unpack_from('<h', payload)[0]), struct.unpack_from('<hh', payload, 4))
            if None in objects:
                objects[objects.index(None)] = item
            else:
                objects.append(item)
        elif function == 0x12D and len(payload) >= 2:
            index = struct.unpack_from('<H', payload)[0]
            current = objects[index] if index < len(objects) else None
        elif function == 0x1F0 and len(payload) >= 2:
            index = struct.unpack_from('<H', payload)[0]
            if index < len(objects):
                objects[index] = None
        elif function == 0x214 and len(payload) >= 4:
            position = struct.unpack_from('<hh', payload)
        elif function == 0x12E and len(payload) >= 2:
            alignment = struct.unpack_from('<H', payload)[0]
        elif function in {0xA32, 0x521}:
            if current is None or current[2] != (0, 0) or alignment & 25 != 25:
                return None
            if function == 0xA32 and len(payload) >= 8:
                count, flags = struct.unpack_from('<HH', payload, 4)
                begin = 16 if flags & 6 else 8
            elif function == 0x521 and len(payload) >= 2:
                count = struct.unpack_from('<H', payload)[0]
                begin = 2
            else:
                return None
            text = payload[begin:begin + count]
            family = current[0]
            if family not in normal and not (family in {'Symbol', 'Euclid Symbol'} and text in {b'-', b'+'}):
                return None
            runs.append((position[1], position[0], current[1], text))
    if len(runs) not in {1, 2} or len({(run[1], run[2]) for run in runs}) != 1:
        return None
    runs.sort()
    if len(runs) == 2 and runs[0][3] not in {b'-', b'+'}:
        return None
    text = b''.join(run[3] for run in runs)
    return text.decode('ascii') if re.fullmatch(rb'[+-]?[0-9]+(?:[.,][0-9]+)?', text) else None
